<?php use App\Core\Helpers as H; ?>
<header class="dashboard-heading"><div><h1>Download history</h1><p class="muted">Files are served only through Asset Moth's protected download route.</p></div><a class="btn alt" href="/browse">Browse products</a></header>
<?php if(!$items):?><section class="card empty-state"><h2>No downloads yet</h2><p>Your eligible purchases will appear here after Stripe confirms payment.</p><a class="btn" href="/browse">Browse marketplace</a></section><?php endif;?>
<div class="responsive-table"><table><thead><tr><th>Product</th><th>Seller</th><th>Purchased</th><th>Order</th><th>Status</th></tr></thead><tbody>
<?php foreach($items as $i): $paid=($i['payment_status']??'')==='paid';$expired=!empty($i['download_expires_at'])&&strtotime($i['download_expires_at'])<time();$downloadable=($i['fulfillment_type']??'downloadable')==='downloadable';$available=$paid&&!$expired&&$downloadable&&!empty($i['file_id'])&&!empty($i['file_available']); ?>
<tr><td><div class="media-row"><?php if($i['preview_image']??null):?><img class="product-thumb" src="<?=H::assetUrl($i['preview_image'])?>" alt=""><?php endif;?><span><a href="/product/<?=H::e($i['slug'])?>"><?=H::e($i['title'])?></a><?php if($i['file_name']??null):?><br><small><?=H::e($i['file_name'])?></small><?php endif;?></span></div></td><td><?php if($i['store_slug']??null):?><a href="/store/<?=H::e($i['store_slug'])?>"><?=H::e($i['seller_name'])?></a><?php else:?><?=H::e($i['seller_name'])?><?php endif;?></td><td><?=H::e($i['purchase_date'])?></td><td><a href="/dashboard/order/<?=(int)$i['order_id']?>">#<?=(int)$i['order_id']?></a></td><td><?php if(($i['payment_status']??'')==='refunded'):?><span class="status-badge danger">Refunded</span><?php elseif($available):?><a class="btn" href="/download/<?=(int)$i['file_id']?>">Download</a><?php elseif(!$downloadable):?><span class="status-badge neutral">Manual delivery</span><?php elseif($expired):?><span class="status-badge danger">Expired</span><?php elseif(!$paid):?><span class="status-badge warning">Unpaid / unavailable</span><?php else:?><span class="status-badge neutral">File unavailable</span><?php endif;?></td></tr>
<?php endforeach;?></tbody></table></div>
